	(834, 7473, 2, 120, 0, 7, '[{"head":1, "body":1, "leg":1, "bag":-1}]', 'Thẻ Thằn lằn bay', 'Thằn lằn bay dùng cái mỏ dài và cứng để tấn công kẻ thù, đôi khi chúng vẫn dùng để gõ hạt óc chó ăn', '[{"id":77,"param":3,"activeCard":0},{"id":77,"param":4,"activeCard":1},{"id":77,"param":5,"activeCard":2}]', 833, 2, -1),
	(835, 7474, 2, 120, 0, 8, '[{"head":1, "body":1, "leg":1, "bag":-1}]', 'Thẻ Phi long', 'Dùng tốc độ cực nhanh để tiếp cận và hạ gục mục tiêu, Phi long cũng có sở thích hơi lạ là khi bay luôn mở to miệng để đón gió', '[{"id":103,"param":3,"activeCard":0},{"id":103,"param":4,"activeCard":1},{"id":103,"param":5,"activeCard":2}]', 834, 2, -1),
	(836, 7475, 2, 120, 0, 9, '[{"head":1, "body":1, "leg":1, "bag":-1}]', 'Thẻ Quỷ bay', 'Sở trường tấn công chớp choáng kẻ thù, nhưng đâu ai ngờ Quỷ bay lại có bệnh sợ độ cao', '[{"id": 94, "param":3, "activeCard": 0}, {"id": 94, "param": 4, "activeCard": 1}, {"id": 94, "param": 5, "activeCard": 2}]', 835, 2, -1),
	(837, 7476, 3, 120, 0, 34, '[{"head":1, "body":1, "leg":1, "bag":-1}]', 'Thẻ Lính độc nhãn', 'Người ta nuôi quân lính dùng trong 1 giờ, Lính độc nhãn thì không dùng được 5 phút', '[{"id": 7, "param":30, "activeCard": 0}, {"id": 0, "param": 5, "activeCard": 1}, {"id": 6, "param": 50, "activeCard": 2}]', 836, 2, -1),
	(838, 7477, 3, 120, 0, 35, '[{"head":1, "body":1, "leg":1, "bag":-1}]', 'Thẻ Lính độc nhãn', 'Người ta nuôi quân lính dùng trong 1 giờ, Lính độc nhãn thì không dùng được 5 phút', '[{"id": 50, "param": 3, "activeCard": 0},\n{"id": 50, "param": 4, "activeCard": 1},\n{"id": 50, "param": 5, "activeCard": 2}]', 837, 2, -1),
	(839, 7478, 3, 120, 0, 36, '[{"head":1, "body":1, "leg":1, "bag":-1}]', 'Thẻ Sói xám', 'Được lính độc nhãn thuần hóa và cho giữ nhà như cún con, sở thích của chúng là được chơi trò nhặt bóng', '[{"id":77,"param":3,"activeCard":0},{"id":77,"param":4,"activeCard":1},{"id":77,"param":5,"activeCard":2}]', 838, 2, -1),
	(840, 7480, 3, 120, 1, 1, '[{"head":141, "body":142, "leg":143, "bag":-1}]', 'Thẻ Trung úy Trắng', 'Thân hình hơi béo so với tiêu chuẩn chung, luôn đeo chiếc khăn quàng đỏ, thường hay mơ mộng làm thơ', '[{"id":103,"param":3,"activeCard":0},{"id":103,"param":4,"activeCard":1},{"id":103,"param":5,"activeCard":2}]', 839, 2, -1),
	(841, 7481, 3, 120, 1, 1, '[{"head":123, "body":124, "leg":125, "bag":-1}]', 'Thẻ Ninja Áo Tím', 'Ninja với nhiều tài năng để trở thành sát thủ, nhưng kỹ thuật ẩn thân lại không có, nên không thể trở thành sát thủ', '[{"id": 94, "param":3, "activeCard": 0}, {"id": 94, "param": 4, "activeCard": 1}, {"id": 94, "param": 5, "activeCard": 2}]', 840, 2, -1),
	(842, 7479, 4, 120, 1, 1, '[{"head":135, "body":136, "leg":137, "bag":64}]', 'Thẻ Trung úy Xanh Lơ', 'Có siêu năng lực thôi miên nhưng cực kỳ sợ chuột', '[{"id": 7, "param":30, "activeCard": 0}, {"id": 0, "param": 5, "activeCard": 1}, {"id": 6, "param": 50, "activeCard": 2}]', 841, 2, -1),
	(859, 1568, 4, 120, 1, 1, '[{"head":144, "body":145, "leg":146, "bag":-1}]', 'Thẻ Độc Nhãn', 'Đầu não của Red Ribbon. Bị chột một mắt. Lúc nhỏ bị mọi người chê là \'Thằng lùn\'', '[{"id": 50, "param": 10, "activeCard": 0},\n{"id": 50, "param": 20, "activeCard": 1},\n{"id": 50, "param": 20, "activeCard": 2}]', 842, 2, -1),
	(1257, 12640, 6, 120, 1, 1, '[{"head":1351, "body":1352, "leg":1353, "bag":-1}]', 'Thẻ Hutao', 'Sự quan tâm đặc biệt đối với cái chết và cuộc sống sau cái chết. Luôn tìm kiếm những phương pháp để bảo vệ linh hồn và tìm hiểu về bí mật của cuộc sống và cái chết', '[{"id": 103, "param": 30, "activeCard": 0},\n{"id": 103, "param": 40, "activeCard": 1},\n{"id": 103, "param": 60, "activeCard": 2}]', 859, 2, -1),
	(1258, 12680, 6, 120, 1, 1, '[{"head":1354, "body":1355, "leg":1356, "bag":-1}]', 'Thẻ Xiao', 'Kỹ năng nguyên tố của Xiao cho phép anh biến thành một hình dạng quỷ đầy sức mạnh trong một khoảng thời gian ngắn', '[{"id": 77, "param": 30, "activeCard": 0},\n{"id": 77, "param": 40, "activeCard": 1},\n{"id": 77, "param": 60, "activeCard": 2}]', 1257, 2, -1),
	(1259, 12714, 6, 120, 1, 1, '[{"head":1357, "body":1358, "leg":1359, "bag":-1}]', 'Thẻ Ayaka', 'Là một người quyết tâm và kiên nhẫn. Không dễ bị lùi bước bởi những khó khăn và luôn cố gắng vượt qua mọi trở ngại để đạt được mục tiêu của mình', '[{"id": 5, "param": 10, "activeCard": 0},\n{"id": 5, "param": 20, "activeCard": 1},\n{"id": 5, "param": 40, "activeCard": 2}]', 1258, 2, -1);
